/* the bounds of a window over [from, to) of `len` elements: a list's or an
   array's storage lent as a SpanVal or a view, or a window split in two. */
static void z_coll_window_check(uint64_t _from, uint64_t _to, uint64_t _len, const char* _who);
static void z_coll_window_check(uint64_t _from, uint64_t _to, uint64_t _len, const char* _who) {
    if (_from > _to || _to > _len) {
        char _zp_buf[160];
        snprintf(_zp_buf, sizeof(_zp_buf), "%s: [%llu, %llu) out of bounds (length %llu)", _who, (unsigned long long)_from, (unsigned long long)_to, (unsigned long long)_len);
        z_panic(_zp_buf);
    }
}
static bool z_t60_isEmpty(const z_t60_t* self);
static bool z_t60_isEmpty(const z_t60_t* self) {
    return self->size == 0;
}

static bool z_t60_isAscii(const z_t60_t* self);
static bool z_t60_isAscii(const z_t60_t* self) {
    for (uint64_t i = 0; i < self->size; i++) {
        if ((unsigned char)self->data[i] >= 0x80) return false;
    }
    return true;
}

static bool z_t60_startsWith(const z_t60_t* self, const z_t60_t* prefix);
static bool z_t60_startsWith(const z_t60_t* self, const z_t60_t* prefix) {
    if (prefix->size > self->size) return false;
    if (prefix->size == 0) return true;
    return memcmp(self->data, prefix->data, prefix->size) == 0;
}

static bool z_t60_endsWith(const z_t60_t* self, const z_t60_t* suffix);
static bool z_t60_endsWith(const z_t60_t* self, const z_t60_t* suffix) {
    if (suffix->size > self->size) return false;
    if (suffix->size == 0) return true;
    return memcmp(self->data + (self->size - suffix->size),
                  suffix->data, suffix->size) == 0;
}

static uint64_t z_t60_indexOf_raw(const z_t60_t* self, const z_t60_t* needle);
static uint64_t z_t60_indexOf_raw(const z_t60_t* self, const z_t60_t* needle) {
    if (needle->size == 0) return 0;
    if (needle->size > self->size) return UINT64_MAX;
    uint64_t last = self->size - needle->size;
    for (uint64_t i = 0; i <= last; i++) {
        if (memcmp(self->data + i, needle->data, needle->size) == 0) {
            return i;
        }
    }
    return UINT64_MAX;
}


static bool z_t60_contains(const z_t60_t* self, const z_t60_t* needle);
static bool z_t60_contains(const z_t60_t* self, const z_t60_t* needle) {
    return z_t60_indexOf_raw(self, needle) != UINT64_MAX;
}

static bool z_ascii_is_ws(unsigned char c);
static bool z_ascii_is_ws(unsigned char c) {
    return c == ' ' || c == '\t' || c == '\n'
        || c == '\v' || c == '\f' || c == '\r';
}

static z_t60_t z_t60_substring(const z_t60_t* self, uint64_t from, uint64_t to);
static z_t60_t z_t60_substring(const z_t60_t* self, uint64_t from, uint64_t to) {
    if (from > self->size || to > self->size || from > to) z_panic("substring: bounds error");
    return (z_t60_t){ .size = to - from, .data = self->data + from };
}
static uint64_t z_t60_hash(const z_t60_t* self);
static uint64_t z_t60_hash(const z_t60_t* self) {
    return z_siphash_stringview(*self);
}
static uint64_t z_t60_fastHash(const z_t60_t* self);
static uint64_t z_t60_fastHash(const z_t60_t* self) {
    return z_fasthash_stringview(*self);
}
static z_t60_t z_t60_trim(const z_t60_t* self);
static z_t60_t z_t60_trim(const z_t60_t* self) {
    const char* p = self->data;
    const char* end = self->data + self->size;
    while (p < end && z_ascii_is_ws((unsigned char)*p)) p++;
    while (end > p && z_ascii_is_ws((unsigned char)end[-1])) end--;
    z_t60_t out = { .size = (uint64_t)(end - p), .data = p };
    return out;
}

static z_t60_t z_t60_trimStart(const z_t60_t* self);
static z_t60_t z_t60_trimStart(const z_t60_t* self) {
    const char* p = self->data;
    const char* end = self->data + self->size;
    while (p < end && z_ascii_is_ws((unsigned char)*p)) p++;
    z_t60_t out = { .size = (uint64_t)(end - p), .data = p };
    return out;
}

static z_t60_t z_t60_trimEnd(const z_t60_t* self);
static z_t60_t z_t60_trimEnd(const z_t60_t* self) {
    const char* p = self->data;
    const char* end = self->data + self->size;
    while (end > p && z_ascii_is_ws((unsigned char)end[-1])) end--;
    z_t60_t out = { .size = (uint64_t)(end - p), .data = p };
    return out;
}

static z_t55_t z_t60_toLowerAscii(const z_t60_t* self);
static z_t55_t z_t60_toLowerAscii(const z_t60_t* self) {
    z_t55_t z = {0};
    z.size = self->size;
    z.capacity = self->size + 1;
    z.data = (char*)z_xmalloc(z.capacity + 1);
    for (uint64_t i = 0; i < self->size; i++) {
        unsigned char c = (unsigned char)self->data[i];
        if (c >= 'A' && c <= 'Z') c = (unsigned char)(c + ('a' - 'A'));
        z.data[i] = (char)c;
    }
    z.data[self->size] = '\0';
    return z;
}

static z_t55_t z_t60_replace_impl(
    const z_t60_t* self, const z_t60_t* needle,
    const z_t60_t* repl, bool once);
static z_t55_t z_t60_replace_impl(
    const z_t60_t* self, const z_t60_t* needle,
    const z_t60_t* repl, bool once) {
    /* empty needle: just copy self */
    if (needle->size == 0) {
        z_t55_t z = {0};
        z.size = self->size;
        z.capacity = self->size + 1;
        z.data = (char*)z_xmalloc(z.capacity + 1);
        memcpy(z.data, self->data, self->size);
        z.data[self->size] = '\0';
        return z;
    }
    /* pass 1: count matches so we can size the output once */
    uint64_t matches = 0;
    if (needle->size <= self->size) {
        uint64_t last = self->size - needle->size;
        uint64_t i = 0;
        while (i <= last) {
            if (memcmp(self->data + i, needle->data, needle->size) == 0) {
                matches++;
                i += needle->size;
                if (once) break;
            } else {
                i++;
            }
        }
    }
    uint64_t delta_per =
        (repl->size > needle->size)
            ? (repl->size - needle->size)
            : 0;
    uint64_t shrink_per =
        (needle->size > repl->size)
            ? (needle->size - repl->size)
            : 0;
    uint64_t out_len = self->size + matches * delta_per - matches * shrink_per;
    z_t55_t z = {0};
    z.size = out_len;
    z.capacity = out_len + 1;
    z.data = (char*)z_xmalloc(z.capacity + 1);
    /* pass 2: copy with replacement */
    uint64_t src_i = 0, dst_i = 0, done_matches = 0;
    while (src_i < self->size) {
        bool can_match = (done_matches < matches)
                      && (src_i + needle->size <= self->size)
                      && (memcmp(self->data + src_i, needle->data, needle->size) == 0);
        if (can_match) {
            memcpy(z.data + dst_i, repl->data, repl->size);
            dst_i += repl->size;
            src_i += needle->size;
            done_matches++;
        } else {
            z.data[dst_i++] = self->data[src_i++];
        }
    }
    z.data[dst_i] = '\0';
    return z;
}

